COMMENT ON TABLE v1_archive."Session" IS 'v1 Session rows, frozen at retirement on 2026-11-25.';
COMMENT ON COLUMN v1_archive."Session"."id" IS 'v1 session id';
COMMENT ON COLUMN v1_archive."Session"."userId" IS 'owner of the session';
COMMENT ON COLUMN v1_archive."Session"."projectId" IS 'project the session ran in';
COMMENT ON COLUMN v1_archive."Session"."repo" IS 'repository the session worked on';
COMMENT ON COLUMN v1_archive."Session"."workspace" IS 'workspace path inside the sandbox';
COMMENT ON COLUMN v1_archive."Session"."executionLocation" IS 'where the session ran, local or cloud';
COMMENT ON COLUMN v1_archive."Session"."title" IS 'session title shown in the v1 clients';
COMMENT ON COLUMN v1_archive."Session"."pinnedAt" IS 'when the operator pinned the session';
COMMENT ON COLUMN v1_archive."Session"."archivedAt" IS 'when the session was archived';
COMMENT ON COLUMN v1_archive."Session"."deletedAt" IS 'when the session was deleted';
COMMENT ON COLUMN v1_archive."Session"."createdAt" IS 'when the session was created';
COMMENT ON COLUMN v1_archive."Session"."updatedAt" IS 'when the session row last changed';
COMMENT ON COLUMN v1_archive."Session"."mainThreadId" IS 'the main thread of the session';
COMMENT ON COLUMN v1_archive."Session"."managedBySessionId" IS 'teammate parent session that manages this session'

COMMENT ON TABLE v1_archive."Thread" IS 'v1 Thread rows, frozen at retirement on 2026-11-25.';
COMMENT ON COLUMN v1_archive."Thread"."id" IS 'v1 thread id';
COMMENT ON COLUMN v1_archive."Thread"."head" IS 'sequence number of the newest committed event';
COMMENT ON COLUMN v1_archive."Thread"."rev" IS 'monotonic revision counter of the thread';
COMMENT ON COLUMN v1_archive."Thread"."historyRev" IS 'revision counter of the context history after rewinds';
COMMENT ON COLUMN v1_archive."Thread"."createdAt" IS 'when the thread was created';
COMMENT ON COLUMN v1_archive."Thread"."updatedAt" IS 'when the thread row last changed';
COMMENT ON COLUMN v1_archive."Thread"."parentThreadId" IS 'thread this thread was forked from';
COMMENT ON COLUMN v1_archive."Thread"."forkSeq" IS 'event sequence the fork started at';
COMMENT ON COLUMN v1_archive."Thread"."forkMode" IS 'how the fork inherited context';
COMMENT ON COLUMN v1_archive."Thread"."spawnerThreadId" IS 'thread that spawned this sub-agent';
COMMENT ON COLUMN v1_archive."Thread"."agentType" IS 'agent type of a sub-agent thread';
COMMENT ON COLUMN v1_archive."Thread"."modelRef" IS 'pinned model of the thread';
COMMENT ON COLUMN v1_archive."Thread"."modelEffort" IS 'pinned reasoning effort of the thread';
COMMENT ON COLUMN v1_archive."Thread"."modelFast" IS 'whether the fast model variant was pinned';
COMMENT ON COLUMN v1_archive."Thread"."userId" IS 'owner of the thread';
COMMENT ON COLUMN v1_archive."Thread"."sessionId" IS 'session the thread belongs to';
COMMENT ON COLUMN v1_archive."Thread"."working" IS 'whether a turn was running';
COMMENT ON COLUMN v1_archive."Thread"."awaiting" IS 'what the thread was waiting on';
COMMENT ON COLUMN v1_archive."Thread"."lastOutcome" IS 'outcome of the last turn';
COMMENT ON COLUMN v1_archive."Thread"."activityAt" IS 'when the thread last had activity';
