COMMENT ON TABLE v1_archive."Event" IS 'v1 Event rows, frozen at retirement on 2026-11-25.';
COMMENT ON COLUMN v1_archive."Event"."id" IS 'v1 event id';
COMMENT ON COLUMN v1_archive."Event"."threadId" IS 'thread the event belongs to';
COMMENT ON COLUMN v1_archive."Event"."seq" IS 'position of the event in the thread';
COMMENT ON COLUMN v1_archive."Event"."runId" IS 'turn that produced the event';
